```cpp
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Creamos un objeto stringstream para usar como entrada para el procesamiento
    std::stringstream ss(markdown);

    // Creamos un stringstream para escribir el texto formateado en HTML
    std::stringstream html;

    // Definimos los caracteres de inicio y final de las etiquetas HTML
    const char* openingTags[] = {"#", "**", "*", "_", "`"};
    const char* closingTags[] = {"</h1>", "</strong>", "</em>", "</u>", "</code>"};

    // Definimos el nivel de anidación para cada etiqueta
    int levels[] = {1, 2, 1, 1, 1};

    // Definimos los nombres de las etiquetas HTML
    const char* tagNames[] = {"h1", "strong", "em", "u", "code"};

    // Variable auxiliar para almacenar el nivel de anidación actual
    int currentLevel = 0;

    // Bucle para procesar cada línea del texto markdown
    std::string line;
    while (std::getline(ss, line)) {
        // Bucle para procesar cada caracter de la línea actual
        for (int I = 0; I < line.length(); i++) {
            // Comprobamos si el caracter actual es inicio de una etiqueta markdown
            for (int j = 0; j < sizeof(openingTags) / sizeof(openingTags[0]); j++) {
                // Si encontramos un inicio de etiqueta, agregamos la correspondiente etiqueta HTML
                if (line.compare(i, sizeof(openingTags[j]) / sizeof(openingTags[j][0]), openingTags[j]) == 0) {
                    // Comprobamos el nivel de anidación actual para agregar la etiqueta correcta
                    html << "<" << tagNames[j] << ">" << std::string(levels[j] * currentLevel, '>') << std::string(levels[j] * (currentLevel - 1), '<');
                    currentLevel += levels[j];
                    i += sizeof(openingTags[j]) / sizeof(openingTags[j][0]) - 1;
                    break;
                }
            }

            // Comprobamos si el caracter actual es final de una etiqueta markdown
            for (int j = 0; j < sizeof(closingTags) / sizeof(closingTags[0]); j++) {
                // Si encontramos un final de etiqueta, cerramos la etiqueta HTML correspondiente
                if (line.compare(i, sizeof(closingTags[j]) / sizeof(closingTags[j][0]), closingTags[j]) == 0) {
                    html << std::string(levels[j] * currentLevel, '<') << std::string(levels[j] * (currentLevel - 1), '>') << "</" << tagNames[j] << ">";
                    currentLevel -= levels[j];
                    i += sizeof(closingTags[j]) / sizeof(closingTags[j][0]) - 1;
                    break;
                }
            }

            // Si el caracter actual no es inicio ni final de una etiqueta markdown, lo agregamos tal cual
            if (i < line.length()) {
                html << line[i];
            }
        }

        // Agregamos una etiqueta para romper el párrafo
        html << "<br/>";
    }

    // Devolvemos el texto formateado en HTML
    return html.str();
}
```

Este código usa una lista estática de caracteres para identificar los comienzos y finales de las etiquetas markdown y HTML. Para soportar diferentes niveles de anidación, se usa un contador para mantener el nivel actual de etiquetas abiertas. El código también agrega una etiqueta `<br/>` para romper los párrafos.

